function CountOpen(brackets: string): int
    requires brackets != null
    ensures 0 <= CountOpen(brackets) <= |brackets|
{
    var count := 0;
    var i := 0;
    while i < |brackets|
        invariant 0 <= count <= i
    {
        if brackets[i] == '(' then
            count := count + 1;
        i := i + 1;
    }
    return count;
}

function CountClose(brackets: string): int
    requires brackets != null
    ensures 0 <= CountClose(brackets) <= |brackets|
{
    var count := 0;
    var i := 0;
    while i < |brackets|
        invariant 0 <= count <= i
    {
        if brackets[i] == ')' then
            count := count + 1;
        i := i + 1;
    }
    return count;
}

function IsWellFormed(brackets: string): bool
    requires brackets != null
    ensures IsWellFormed(brackets) == (CountBalance(brackets) == 0)
{
    var balance := 0;
    var i := 0;
    while i < |brackets|
        invariant 0 <= balance <= i
    {
        if brackets[i] == '(' then
            balance := balance + 1;
        else if brackets[i] == ')' then
            balance := balance - 1;
        if balance < 0 then
            return false;
        i := i + 1;
    }
    return balance == 0;
}

function CountBalance(brackets: string): int
    requires brackets != null
    ensures CountBalance(brackets) == CountOpen(brackets) - CountClose(brackets)
{
    return CountOpen(brackets) - CountClose(brackets);
}
